<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { ArrowRight, ArrowUpRight, CalendarClock, Check, CheckCircle2, ChevronRight, CircleDollarSign, Clock3, Download, FileCheck2, FileText, FolderKanban, History, Plus, Search, ShieldCheck, UsersRound, X } from 'lucide-vue-next'
import PageContainer from '@/shared/components/PageContainer.vue'
import GovernanceManagement from './GovernanceManagement.vue'
import { useGovernanceStore, blankProject } from '../store'
import { roles, stages, members, criteria, decisionLabels, documentKinds, today, stageTitle, actLabels, dueDate, actDue, money, costTotal, councilErrors, type Project, type Act, type DocumentKind, type Decision, type CostRow } from '../domain'
const props = withDefaults(defineProps<{ pageKey: string; projectId?: string }>(), { projectId: '' })
const store = useGovernanceStore()
const router = useRouter()
const route = useRoute()
const base = '/apps/project-governance'
const query = ref('')
const status = ref('all')
const tab = ref('overview')
const feedback = ref('')
const failure = ref(false)
const createDialog = ref<HTMLDialogElement>()
const actDialog = ref<HTMLDialogElement>()
const form = reactive(blankProject())
const edit = reactive(blankProject())
const technical = reactive({ requirement: '', assignment: '', estimate: '', orderRef: '', contractRef: '', expertiseRequired: false })
const current = computed(() => store.projects.find(p => p.id === props.projectId))
const editable = computed(() => current.value && store.role === 'initiator' && ['draft', 'returned'].includes(current.value.stage))
const docKind = ref<DocumentKind>('concept')
const returnNote = ref('')
const actNote = reactive<Record<string, string>>({})
const actDraft = reactive({ month: today().slice(0, 7), amount: 0, progress: 0, services: '', reportName: '' })
const reportFile = ref<File>()
const costRows = ref<CostRow[]>([])
const holidaysInput = ref('')
const financial = computed(() => { try { return costTotal(costRows.value) } catch { return { salary: 0, overhead: 0, total: 0 } } })
const viewProjects = computed(() => store.projects.filter(p => (!query.value || `${p.id} ${p.title} ${p.owner} ${p.organization}`.toLowerCase().includes(query.value.toLowerCase())) && (status.value === 'all' || p.stage === status.value) && (props.pageKey !== 'council' || ['intake', 'council', 'returned', 'supported', 'rejected'].includes(p.stage))))
const currentActs = computed(() => store.acts.filter(a => a.projectId === current.value?.id))
const totalPaid = computed(() => store.acts.filter(a => a.state === 'paid').reduce((s, a) => s + a.amount, 0))
const pendingActs = computed(() => store.acts.filter(a => !['paid', 'draft'].includes(a.state)))
const jobs = computed(() => [
  ...store.projects.map(p => ({ id: p.id, title: p.title, due: dueDate(p, store.holidays), stage: stageTitle(p.stage), owner: `${store.assignedName(p, stages.find(s => s.id === p.stage)?.owner)} · ${roles.find(r => r.id === stages.find(s => s.id === p.stage)?.owner)?.title || ''}`, projectId: p.id })),
  ...store.acts.map(a => ({ id: a.id, title: store.project(a.projectId).title, due: actDue(a, store.holidays), stage: actLabels[a.state], owner: a.state === 'submitted' ? 'Tashabbuskor + BTRTR' : a.state === 'sent' ? 'Jamg‘arma' : 'Markaz', projectId: a.projectId })),
].filter(j => j.due).sort((a, b) => a.due.localeCompare(b.due)))
const overdue = computed(() => jobs.value.filter(j => j.due < today()))
const nextLabels: Record<string, string> = { draft: 'Kengash kotibiga yuborish', intake: 'Kengash ko‘rigiga qabul qilish', returned: 'Qayta taqdim etish', supported: 'Konsepsiyaga rozilik berish', concept: 'Texnik talabni Markazga berish', requirements: 'TTni tasdiqlashga yuborish', assignment: 'Texnik topshiriqni tasdiqlash', technical: 'Loyiha buyrug‘ini tasdiqlash', ordered: 'Shartnomani qayd etish' }
const ownerRole = computed(() => stages.find(s => s.id === current.value?.stage)?.owner)
const canUpload = computed(() => current.value && ({ draft: 'initiator', returned: 'initiator', concept: 'initiator', requirements: 'center', assignment: 'center', technical: 'director', ordered: 'center' } as Record<string, string>)[current.value.stage] === store.role)
const canSaveTechnical = computed(() => current.value && ({ concept: 'initiator', requirements: 'center', technical: 'director', ordered: 'center' } as Record<string, string>)[current.value.stage] === store.role)
watch(() => [props.projectId, route.query.tab], () => {
  tab.value = typeof route.query.tab === 'string' ? route.query.tab : 'overview'
  if (current.value) { Object.assign(edit, structuredClone(JSON.parse(JSON.stringify(current.value)))); Object.assign(technical, current.value); costRows.value = current.value.costs.map(r => ({ ...r })) }
}, { immediate: true })
watch(() => props.pageKey, () => { query.value = ''; status.value = 'all'; feedback.value = '' })
function run(action: () => void, success = 'Amal demo rejimida bajarildi.') { try { action(); feedback.value = success; failure.value = false } catch (e) { failure.value = true; feedback.value = e instanceof Error ? e.message : 'Amal bajarilmadi.' } }
function newProject() { feedback.value = ''; failure.value = false; Object.assign(form, blankProject()); createDialog.value?.showModal() }
function createProject() { run(() => { const p = store.create(form); createDialog.value?.close(); router.push(`${base}/projects/${p.id}`) }, 'Yangi loyiha yaratildi. Konsepsiyani to‘ldirib yuboring.') }
function advanceProject() { if (current.value) run(() => store.next(current.value!.id)) }
function recordConclusion(decision: Decision) { if (current.value) run(() => store.conclusion(current.value!.id, decision), 'Kengash xulosasi va bayonnoma auditga qayd etildi.') }
function upload(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (file && current.value) run(() => store.upload(current.value!.id, docKind.value, file), 'Hujjat biriktirildi. Fayl faqat ushbu demo sessiyada saqlanadi.'); (event.target as HTMLInputElement).value = '' }
function openActForm() { feedback.value = ''; failure.value = false; Object.assign(actDraft, { month: today().slice(0, 7), amount: 0, progress: 0, services: '', reportName: '' }); reportFile.value = undefined; actDialog.value?.showModal() }
function chooseReport(e: Event) { reportFile.value = (e.target as HTMLInputElement).files?.[0]; actDraft.reportName = reportFile.value?.name || '' }
function createAct() { run(() => { if (!reportFile.value || !current.value) throw new Error('Hisobot faylini tanlang.'); store.createAct(current.value.id, actDraft, reportFile.value); actDialog.value?.close() }, 'Dalolatnoma qoralamasi yaratildi.') }
function download(name: string, contents: Blob | string, type = 'text/plain;charset=utf-8') { const url = URL.createObjectURL(contents instanceof Blob ? contents : new Blob([contents], { type })); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
function exportProject() { if (!current.value) return; const p = current.value; download(`${p.id}-demo.json`, JSON.stringify({ ...p, documents: p.documents.map(({ file: _file, ...d }) => d), acts: currentActs.value, notice: 'Demo ma’lumotlari. Fayllarning o‘zi eksportga kiritilmagan.' }, null, 2), 'application/json') }
function downloadDocument(d: Project['documents'][number]) { if (d.file) download(d.name, d.file); else download(d.name, `DEMO HUJJAT\n${current.value?.title}\n${d.kind}\n${current.value?.requirement}\n${current.value?.assignment}\nBu haqiqiy imzolangan hujjat emas.`) }
function escape(s: string) { return s.replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]!)) }
function downloadReport(a: Act) { const file = store.reportFiles.get(a.id); if (file) download(file.name, file); else download(a.reportName, `DEMO HISOBOT\n${a.services}\n${a.month}\nBu demo namuna.`) }
function exportAct(a: Act) { const p = store.project(a.projectId); download(`${a.id}-dalolatnoma.html`, `<!doctype html><html lang="uz"><meta charset="utf-8"><title>${escape(a.id)}</title><style>body{font:16px Arial;max-width:1100px;margin:40px auto;line-height:1.6}table{border-collapse:collapse;width:100%}td,th{border:1px solid #888;padding:12px}.note{color:#b45309}</style><h1>Bajarilgan ishlar dalolatnomasi</h1><p class="note">DEMO SHAKL · Elektron imzo qo‘yilmagan. Haqiqiy to‘lovni tasdiqlamaydi.</p><p>${escape(p.title)} · ${escape(a.month)} · ${escape(a.id)}</p><p>Buyruq: ${escape(p.orderRef)}. Shartnoma: ${escape(p.contractRef)}.</p><table><tr><th>Xizmatlar</th><th>Shartnoma summasi</th><th>Bajarilish</th><th>Hisobot oyi summasi</th></tr><tr><td>${escape(a.services)}</td><td>${money(p.budget)}</td><td>${a.progress}%</td><td>${money(a.amount)}</td></tr></table><p>Holat: ${escape(actLabels[a.state])}. Hisob-faktura: ${escape(a.invoice || '—')}.</p><p>Tashabbuskor kelishuvi: ${escape(a.agreed.initiator || '—')}. BTRTR kelishuvi: ${escape(a.agreed.reviewer || '—')}.</p><p>Topshiruvchi: Markaz rahbari, bosh hisobchi, loyiha mas’uli.</p><p>Qabul qiluvchi: tashabbuskor mas’uli, BTRTR vakili, Jamg‘arma buxgalteriya vakili.</p><p>Tasdiqlovchi: loyiha yo‘nalishi bo‘yicha mas’ul direktor o‘rinbosari.</p><p>Bu ixcham demo eksport; 346-son buyruq ilovasidagi rasmiy shaklning to‘liq o‘rnini bosmaydi.</p></html>`, 'text/html;charset=utf-8') }
function saveHolidays() { run(() => { const dates = holidaysInput.value.split(/[,\s]+/).filter(Boolean); if (dates.some(d => !/^\d{4}-\d{2}-\d{2}$/.test(d) || Number.isNaN(Date.parse(d)))) throw new Error('Sanalarni YYYY-MM-DD ko‘rinishida kiriting.'); store.holidays = [...new Set(dates)] }, 'Demo ish kunlari kalendari yangilandi.') }
const pipeline = stages.slice(0, 10)
</script>

<template>
  <PageContainer>
    <div class="gov-page">
      <header class="gov-header">
        <div v-if="pageKey === 'detail' && current" class="gov-project-heading"><h2>{{ current.title }}</h2></div>
        <div class="gov-header-actions"><label class="gov-role">Demo rol<select v-model="store.role" aria-label="Demo rol"><option v-for="r in roles" :key="r.id" :value="r.id">{{ r.title }}</option></select></label><label v-if="store.eligibleActors.length" class="gov-role">Demo xodim<select v-model="store.actingPersonId" aria-label="Demo xodim"><option v-for="p in store.eligibleActors" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><button v-if="store.role === 'initiator'" class="gov-primary" @click="newProject"><Plus :size="16" /> Yangi loyiha</button></div>
      </header>
      <div class="gov-demo"><ShieldCheck :size="16" /><span><b>Ishlaydigan demo.</b> Rollar sinov uchun almashtiriladi. Ma’lumotlar va fayllar sahifa yangilanguncha saqlanadi. Elektron imzo va haqiqiy to‘lov ulanmagan.</span></div>
      <div v-if="feedback" :class="['gov-feedback', { error: failure }]" role="status">{{ feedback }}<button aria-label="Xabarni yopish" @click="feedback = ''"><X :size="16" /></button></div>

      <GovernanceManagement v-if="pageKey === 'management'" />
      <template v-else-if="pageKey === 'overview'">
        <section class="gov-hero"><div><span class="gov-pill">ISH JARAYONI KO‘RINADIGAN BO‘LSIN</span><h2>Har bir loyiha. Har bir qaror.<br><em>Har bir mas’ul.</em></h2><p>Kimda to‘xtaganini taxmin qilish shart emas. Qaror, hujjat va muddat bir loyiha kartasida.</p><RouterLink :to="`${base}/projects`" class="gov-primary">Loyihalarni ko‘rish <ArrowRight :size="17" /></RouterLink></div><div class="gov-hero-path"><div v-for="(s, i) in [pipeline[0]!, pipeline[2]!, pipeline[7]!, pipeline[9]!]" :key="s.id"><span>{{ String(i + 1).padStart(2, '0') }}</span><b>{{ s.title }}</b><CheckCircle2 v-if="i < 3" :size="19" /><Clock3 v-else :size="19" /></div><small>79-son buyruq: Kengashning ijobiy xulosasi keyingi bosqich uchun shart.</small></div></section>
        <section class="gov-metrics"><article><FolderKanban /><span>Jami loyihalar</span><strong>{{ store.projects.length }}</strong><small>{{ store.projects.filter(p => p.stage === 'active').length }} tasi ijroda</small></article><article><UsersRound /><span>Kengashda</span><strong>{{ store.projects.filter(p => ['intake', 'council'].includes(p.stage)).length }}</strong><small>10 a’zo · kvorum kamida 7</small></article><article class="warning"><CalendarClock /><span>Muddati o‘tgan</span><strong>{{ overdue.length }}</strong><small>Javobsizlik avtomatik rozilik emas</small></article><article><CircleDollarSign /><span>Moliyalashtirilgan · demo</span><strong class="gov-money">{{ money(totalPaid) }}</strong><small>Faqat «Moliyalashtirilgan» yozuvlar</small></article></section>
        <div class="gov-two"><section class="gov-panel"><div class="gov-panel-title"><h3>E’tibor talab etadi</h3><RouterLink :to="`${base}/monitoring`">Barchasi <ArrowUpRight :size="14" /></RouterLink></div><RouterLink v-for="job in overdue.slice(0, 4)" :key="job.id" :to="`${base}/projects/${job.projectId}`" class="gov-task"><span class="gov-task-icon"><Clock3 :size="19" /></span><div><b>{{ job.title }}</b><small>{{ job.id }} · {{ job.owner }}</small></div><span class="gov-date late">{{ job.due }}</span><ChevronRight :size="16" /></RouterLink></section><section class="gov-panel"><div class="gov-panel-title"><h3>So‘nggi loyihalar</h3><RouterLink :to="`${base}/projects`">Reyestr <ArrowUpRight :size="14" /></RouterLink></div><RouterLink v-for="p in store.projects.slice(0, 4)" :key="p.id" :to="`${base}/projects/${p.id}`" class="gov-task"><span class="gov-task-icon green"><FolderKanban :size="18" /></span><div><b>{{ p.title }}</b><small>{{ p.id }} · {{ p.owner }}</small></div><span class="gov-status" :data-state="p.stage">{{ stageTitle(p.stage) }}</span></RouterLink></section></div>
      </template>

      <template v-else-if="['projects', 'council'].includes(pageKey)">
        <div v-if="pageKey === 'council'" class="gov-council-banner"><UsersRound :size="31" /><div><b>10 a’zo → kamida 7 qatnashuvchi → oddiy ko‘pchilik ovozi</b><p>Qo‘llab-quvvatlash, qayta ishlash yoki maqsadga muvofiq emas deb topish. Har bir xulosa bayonnoma bilan.</p></div><span>79-son · 7, 11–12-bandlar</span></div>
        <div class="gov-toolbar"><label class="gov-search"><Search :size="17" /><input v-model="query" placeholder="Loyiha, raqam yoki mas’ulni qidiring" aria-label="Loyihalarni qidirish"></label><select v-model="status" aria-label="Loyiha holati"><option value="all">Barcha holatlar</option><option v-for="s in stages" :key="s.id" :value="s.id">{{ s.title }}</option></select><span>{{ viewProjects.length }} ta loyiha</span></div>
        <section class="gov-panel gov-table-wrap"><table><thead><tr><th>Loyiha / tashabbuskor</th><th>Joriy bosqich</th><th>Mas’ul</th><th>Qiymat</th><th>Nazorat sanasi</th><th></th></tr></thead><tbody><tr v-for="p in viewProjects" :key="p.id"><td><RouterLink :to="`${base}/projects/${p.id}`"><b>{{ p.title }}</b></RouterLink><small>{{ p.id }} · {{ p.organization }}</small></td><td><span class="gov-status" :data-state="p.stage">{{ stageTitle(p.stage) }}</span></td><td>{{ p.owner }}</td><td class="gov-nowrap">{{ money(p.budget) }}</td><td><span :class="['gov-date', { late: dueDate(p, store.holidays) && dueDate(p, store.holidays) < today() }]">{{ dueDate(p, store.holidays) || '—' }}</span></td><td><RouterLink :to="`${base}/projects/${p.id}`" aria-label="Loyiha kartasini ochish"><ArrowUpRight :size="18" /></RouterLink></td></tr><tr v-if="!viewProjects.length"><td colspan="6" class="gov-empty">Tanlangan filtr bo‘yicha loyiha topilmadi.</td></tr></tbody></table></section>
      </template>

      <template v-else-if="pageKey === 'detail' && current">
        <div class="gov-detail-top"><RouterLink :to="`${base}/projects`">← Loyihalar</RouterLink><span>{{ current.id }}</span><span class="gov-status" :data-state="current.stage">{{ stageTitle(current.stage) }}</span><button @click="exportProject"><Download :size="15" /> Kartani eksport qilish</button></div>
        <section class="gov-pipeline"><div v-for="(s, i) in pipeline" :key="s.id" :class="{ selected: s.id === current.stage, done: pipeline.findIndex(x => x.id === current?.stage) > i }"><span><Check v-if="pipeline.findIndex(x => x.id === current?.stage) > i" :size="13" /><template v-else>{{ i + 1 }}</template></span><b>{{ s.title }}</b></div></section>
        <section class="gov-current"><div><span>JORIY MAS’UL LAVOZIM</span><b>{{ store.assignedName(current, ownerRole) }}</b><small>{{ roles.find(r => r.id === ownerRole)?.title }}</small><small>{{ stages.find(s => s.id === current?.stage)?.rule }}</small></div><div><span>NAZORAT SANASI</span><b :class="{ 'gov-late-text': dueDate(current, store.holidays) && dueDate(current, store.holidays) < today() }">{{ dueDate(current, store.holidays) || 'Alohida muddat belgilanmagan' }}</b><small>Demo kalendari · boshlanish sanasidan keyingi kundan</small></div><button v-if="nextLabels[current.stage] && ownerRole === store.role" class="gov-primary" @click="advanceProject">{{ nextLabels[current.stage] }} <ArrowRight :size="15" /></button></section>
        <nav class="gov-tabs" aria-label="Loyiha kartasi bo‘limlari"><button v-for="t in [{ id: 'overview', name: 'Konsepsiya' }, { id: 'council', name: 'Kengash' }, { id: 'documents', name: 'Texnik hujjatlar' }, { id: 'costs', name: 'Smeta' }, { id: 'acts', name: 'Dalolatnomalar' }, { id: 'history', name: 'Harakatlar tarixi' }]" :key="t.id" :class="{ active: tab === t.id }" @click="tab = t.id">{{ t.name }}</button></nav>
        <section v-if="tab === 'overview'" class="gov-panel gov-pad"><div class="gov-panel-title"><h3>Loyiha konsepsiyasi</h3><span>{{ editable ? 'Tahrirlash mumkin' : 'Ko‘rish rejimi' }}</span></div><form class="gov-form-grid" @submit.prevent="run(() => store.save(current!.id, edit), 'Konsepsiya saqlandi.')"><label>Loyiha nomi<input v-model="edit.title" :disabled="!editable" required></label><label>Tashabbuskor tashkilot<select v-model="edit.organizationId" :disabled="!editable" required @change="edit.unitId = ''; edit.ownerPositionId = ''"><option value="">Tanlang</option><option v-for="o in store.directory.organizations.filter(o => o.active || o.id === current?.organizationId)" :key="o.id" :value="o.id">{{ o.name }}</option></select></label><label>Tarkibiy bo‘linma<select v-model="edit.unitId" :disabled="!editable" required @change="edit.ownerPositionId = ''"><option value="">Tanlang</option><option v-for="u in store.directory.units.filter(u => u.organizationId === edit.organizationId && (u.active || u.id === current?.unitId))" :key="u.id" :value="u.id">{{ u.name }}</option></select></label><label>Mas’ul lavozim<select v-model="edit.ownerPositionId" :disabled="!editable" required><option value="">Tanlang</option><option v-for="p in store.directory.positions.filter(p => p.organizationId === edit.organizationId && p.unitId === edit.unitId && p.roles.includes('initiator') && (p.active || p.id === current?.ownerPositionId))" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label>Yakunlash muddati<input v-model="edit.expectedEnd" type="date" :disabled="!editable" required></label><label>Taxminiy qiymat, so‘m<input v-model.number="edit.budget" type="number" min="0" :disabled="!editable"></label><label>Resurslar<input v-model="edit.resources" :disabled="!editable"></label><label>Maqsad va vazifalar<textarea v-model="edit.purpose" :disabled="!editable" rows="3" /></label><label>Kutilayotgan natijalar<textarea v-model="edit.results" :disabled="!editable" rows="3" /></label><label class="gov-full">Texnik yechim<textarea v-model="edit.solution" :disabled="!editable" rows="3" /></label><label v-if="current.stage === 'returned'" class="gov-full">E’tirozlar bo‘yicha tuzatish va tushuntirish<textarea v-model="edit.revision" :disabled="!editable" rows="3" /><small>Kengash sababi: {{ current.council.reason }} · qayta topshirish: {{ current.revisionDue }}</small></label><div v-if="editable" class="gov-full"><button class="gov-primary" type="submit">Konsepsiyani saqlash</button></div></form><div v-if="current.stage === 'intake' && store.role === 'secretary'" class="gov-objection"><label>Paket kamchiliklari<textarea v-model="returnNote" placeholder="9-band talablariga mos kelmagan qismlarni ko‘rsating" /></label><button class="gov-danger" @click="run(() => store.sendBack(current!.id, returnNote))">Paketni tashabbuskorga qaytarish</button></div><p v-if="current.stage === 'returned' && current.revisionDue < today()" class="gov-warning">Kengash belgilagan qayta topshirish muddati o‘tgan. Ushbu kartani qayta topshirish bloklangan; yangi tashabbus yaratish mumkin.</p></section>
        <section v-if="tab === 'council'" class="gov-panel gov-pad"><div class="gov-panel-title"><h3>Kengash majlisi va ovozlar</h3><span class="gov-status">{{ current.council.present.length }}/10 qatnashuvchi</span></div><p class="gov-muted">Bu demo rejimda kotib yoki Kengash roli ovozlarni sinov uchun qayd etadi. Haqiqiy a’zolar autentifikatsiyasi va imzolangan bayonnoma server integratsiyasini talab qiladi.</p><fieldset :disabled="!['secretary', 'council'].includes(store.role) || current.stage !== 'council'"><div class="gov-two"><div><h4>Qatnashuv va ovoz berish</h4><div v-for="m in members" :key="m" class="gov-vote"><label><input v-model="current.council.present" type="checkbox" :value="m">{{ m }}</label><select v-if="current.council.present.includes(m)" v-model="current.council.votes[m]" :aria-label="`${m} ovozi`"><option :value="undefined">Ovoz tanlang</option><option value="support">Qo‘llab-quvvatlash</option><option value="return">Qayta ishlash</option><option value="reject">Maqsadga muvofiq emas</option><option value="abstain">Betaraf</option></select></div></div><div><h4>Baholashning 7 mezoni</h4><label v-for="criterion in criteria" :key="criterion" class="gov-check"><input v-model="current.council.checks" type="checkbox" :value="criterion">{{ criterion }}</label><label class="gov-field">Bayonnoma raqami<input v-model="current.council.protocol" placeholder="Masalan: K-2026-15"></label><label class="gov-field">Qayta ishlash muddati, ish kuni (1–30)<input v-model.number="current.council.revisionDays" type="number" min="1" max="30" placeholder="30"></label><label class="gov-field">E’tiroz / rad etish asoslari<textarea v-model="current.council.reason" rows="3" /></label></div></div></fieldset><div v-if="current.stage === 'council' && store.role === 'council'" class="gov-decisions"><button v-for="d in [{ id: 'support', text: 'Qo‘llab-quvvatlash' }, { id: 'return', text: 'Qayta ishlashga qaytarish' }, { id: 'reject', text: 'Maqsadga muvofiq emas' }]" :key="d.id" :title="councilErrors(current, d.id as Decision).join(' ')" @click="recordConclusion(d.id as Decision)">{{ d.text }}</button></div><p v-if="current.council.decision" class="gov-success">Qayd etilgan xulosa: {{ decisionLabels[current.council.decision] }} · {{ current.council.protocol }} · {{ current.council.date }}</p></section>
        <section v-if="tab === 'documents'" class="gov-panel gov-pad"><div class="gov-panel-title"><h3>Texnik hujjatlar va rekvizitlar</h3><span>{{ current.documents.length }} ta hujjat</span></div><div class="gov-form-grid"><label>Texnik talab<textarea v-model="technical.requirement" :disabled="!(current.stage === 'concept' && store.role === 'initiator')" rows="4" /></label><label>Texnik topshiriq<textarea v-model="technical.assignment" :disabled="!(current.stage === 'requirements' && store.role === 'center')" rows="4" /></label><label>Oyma-oy smeta mazmuni<textarea v-model="technical.estimate" :disabled="!(current.stage === 'requirements' && store.role === 'center')" rows="3" /></label><div><label class="gov-field">Loyiha buyrug‘i raqami<input v-model="technical.orderRef" :disabled="!(current.stage === 'technical' && store.role === 'director')"></label><label class="gov-field">Shartnoma raqami<input v-model="technical.contractRef" :disabled="!(current.stage === 'ordered' && store.role === 'center')"></label><label class="gov-check"><input v-model="technical.expertiseRequired" type="checkbox" :disabled="!(current.stage === 'requirements' && store.role === 'center')">Qonunchilikka ko‘ra ekspertiza talab etiladi</label></div></div><button v-if="canSaveTechnical" class="gov-primary" @click="run(() => store.saveTechnical(current!.id, technical), 'Rekvizitlar saqlandi.')">Rekvizitlarni saqlash</button><div v-if="canUpload" class="gov-upload"><FileText :size="25" /><div><b>Hujjatni biriktiring</b><p>PDF, DOCX yoki boshqa fayl · 20 MBgacha · demo sessiya</p></div><select v-model="docKind" aria-label="Hujjat turi"><option v-for="d in documentKinds" :key="d.id" :value="d.id">{{ d.title }}</option></select><input type="file" aria-label="Hujjat fayli" @change="upload"></div><div v-for="d in current.documents" :key="d.id" class="gov-doc-row"><FileText :size="20" /><div><b>{{ d.name }}</b><small>{{ documentKinds.find(k => k.id === d.kind)?.title }} · {{ d.date }} {{ d.demo ? '· demo namuna' : '' }}</small></div><button @click="downloadDocument(d)"><Download :size="16" /> Yuklab olish</button></div><p v-if="!current.documents.length" class="gov-empty">Hali hujjat biriktirilmagan.</p></section>
        <section v-if="tab === 'costs'" class="gov-panel gov-pad"><h3>Mutaxassislar va loyiha qiymati</h3><p class="gov-warning">346-son nusxada tariflar jadvali mavjud emas. Quyidagi tariflar foydalanuvchi kiritadigan demo qiymatlar; rasmiy stavka sifatida olinmaydi. Kishi/soat alohida, mehnat haqi esa mutaxassis × oy × oylik stavka asosida hisoblanadi.</p><div class="gov-table-wrap"><table class="gov-cost-table"><thead><tr><th>Toifa / ish turi</th><th>Soni</th><th>Oylik stavka</th><th>Oy</th><th>Kishi/soat</th></tr></thead><tbody><tr v-for="(r, i) in costRows" :key="i"><td><input v-model="r.category" aria-label="Mutaxassis toifasi"></td><td><input v-model.number="r.count" type="number" min="0" step="1" aria-label="Mutaxassislar soni"></td><td><input v-model.number="r.monthlyRate" type="number" min="0" aria-label="Oylik stavka"></td><td><input v-model.number="r.months" type="number" min="0" aria-label="Oylar soni"></td><td><input v-model.number="r.hours" type="number" min="0" aria-label="Kishi soat"></td></tr></tbody></table></div><div class="gov-cost-summary"><div><span>Ish haqi jamg‘armasi</span><b>{{ money(financial.salary) }}</b></div><Plus :size="20" /><div><span>Boshqa xarajatlar · 5%</span><b>{{ money(financial.overhead) }}</b></div><ArrowRight :size="20" /><div><span>Loyiha qiymati</span><b>{{ money(financial.total) }}</b></div></div><div v-if="store.role === 'center' && current.stage === 'requirements'" class="gov-actions"><button @click="costRows.push({ category: 'Yangi mutaxassis', count: 1, monthlyRate: 0, months: 1, hours: 0 })"><Plus :size="15" /> Qator qo‘shish</button><button class="gov-primary" @click="run(() => store.saveCost(current!.id, costRows.map(r => ({ ...r }))), 'Smeta va loyiha qiymati yangilandi.')">Demo smetani saqlash</button></div></section>
        <section v-if="tab === 'acts'" class="gov-panel gov-pad"><div class="gov-panel-title"><h3>Oylik ishlarni qabul qilish</h3><button v-if="store.role === 'center' && current.stage === 'active'" class="gov-primary" @click="openActForm"><Plus :size="16" /> Yangi dalolatnoma</button></div><article v-for="a in currentActs" :key="a.id" class="gov-act"><div class="gov-act-heading"><div><b>{{ a.id }} · {{ a.month }}</b><p>{{ a.services }}</p></div><span class="gov-status" :data-state="a.state">{{ actLabels[a.state] }}</span></div><div class="gov-act-facts"><span><small>Hisobot oyi summasi</small><b>{{ money(a.amount) }}</b></span><span><small>Bajarilish</small><b>{{ a.progress }}%</b></span><span><small>Nazorat sanasi</small><b :class="{ 'gov-late-text': actDue(a, store.holidays) && actDue(a, store.holidays) < today() }">{{ actDue(a, store.holidays) || '—' }}</b></span></div><div class="gov-agreements"><span :class="{ yes: a.agreed.initiator }"><CheckCircle2 :size="16" /> Tashabbuskor {{ a.agreed.initiator || '· kutilmoqda' }}</span><span :class="{ yes: a.agreed.reviewer }"><CheckCircle2 :size="16" /> BTRTR {{ a.agreed.reviewer || '· kutilmoqda' }}</span><span :class="{ yes: a.approved }"><ShieldCheck :size="16" /> Tasdiqlash {{ a.approved || '· kutilmoqda' }}</span></div><p v-if="a.objection" class="gov-warning">E’tiroz: {{ a.objection }}. Tuzatish muddati buyruqda alohida belgilanmagan.</p><label v-if="a.state === 'objection' && store.role === 'center'" class="gov-field">Tuzatish bo‘yicha izoh<textarea v-model="a.correction" /></label><label v-if="a.state === 'submitted' && ['initiator', 'reviewer'].includes(store.role)" class="gov-field">E’tiroz sababi, agar mavjud bo‘lsa<input v-model="actNote[a.id]" placeholder="Aniq kamchilikni yozing"></label><label v-if="a.state === 'approved' && store.role === 'center'" class="gov-field">Hisob-faktura raqami<input v-model="a.invoice" placeholder="HF-2026-..."></label><div class="gov-actions"><button @click="downloadReport(a)"><FileText :size="15" /> Hisobot fayli</button><button @click="exportAct(a)"><Download :size="15" /> Demo shakl</button><button v-if="store.role === 'center' && ['draft', 'objection'].includes(a.state)" class="gov-primary" @click="run(() => store.actStep(a.id, 'submit'))">Kelishishga yuborish</button><template v-if="a.state === 'submitted' && ['initiator', 'reviewer'].includes(store.role)"><button class="gov-primary" :disabled="!!a.agreed[store.role as 'initiator' | 'reviewer']" @click="run(() => store.actStep(a.id, 'agree'))">Kelishish</button><button class="gov-danger" @click="run(() => store.actStep(a.id, 'object', actNote[a.id] || ''))">E’tiroz bildirish</button></template><button v-if="a.state === 'agreed' && store.role === 'director'" class="gov-primary" @click="run(() => store.actStep(a.id, 'approve'))">Tasdiqlash</button><button v-if="a.state === 'approved' && store.role === 'center'" class="gov-primary" @click="run(() => store.actStep(a.id, 'send'))">Jamg‘armaga yuborish</button><button v-if="a.state === 'sent' && store.role === 'fund'" class="gov-primary" @click="run(() => store.actStep(a.id, 'pay'), 'Demo moliyalashtirish qayd etildi. Haqiqiy pul o‘tkazilmadi.')">Moliyalashtirishni qayd etish · demo</button></div><details v-if="a.audit.length"><summary>Dalolatnoma tarixi · {{ a.audit.length }}</summary><p v-for="event in a.audit" :key="event.id" class="gov-muted">{{ event.at }} · {{ event.actorName || roles.find(r => r.id === event.role)?.title }} · {{ event.action }} · {{ event.details }}</p></details></article><p v-if="!currentActs.length" class="gov-empty">Hali dalolatnoma yaratilmagan. Shartnomali faol loyihada Markaz yangi hisobot oyini boshlaydi.</p></section>
        <section v-if="tab === 'history'" class="gov-panel gov-pad"><h3>Harakatlar tarixi</h3><div v-for="event in current.audit" :key="event.id" class="gov-history"><History :size="18" /><div><b>{{ event.action }}</b><p>{{ event.actorName ? `Bajargan: ${event.actorName} · ` : '' }}{{ event.details }}</p><small>{{ new Date(event.at).toLocaleString('uz-UZ', { timeZone: 'Asia/Tashkent' }) }} · {{ roles.find(r => r.id === event.role)?.title }}</small></div></div></section>
      </template>
      <p v-else-if="pageKey === 'detail'" class="gov-empty">Loyiha topilmadi. <RouterLink :to="`${base}/projects`">Reyestrga qaytish</RouterLink></p>

      <template v-else-if="['acts', 'finance'].includes(pageKey)">
        <section v-if="pageKey === 'finance'" class="gov-metrics"><article><CircleDollarSign /><span>Loyiha qiymatlari jami</span><strong class="gov-money">{{ money(store.projects.reduce((s, p) => s + p.budget, 0)) }}</strong><small>Tasdiqlanmagan loyihalar ham kiritilgan</small></article><article><CheckCircle2 /><span>Moliyalashtirilgan · demo</span><strong class="gov-money">{{ money(totalPaid) }}</strong><small>{{ store.acts.filter(a => a.state === 'paid').length }} ta dalolatnoma</small></article><article><Clock3 /><span>Jarayondagi summa</span><strong class="gov-money">{{ money(pendingActs.reduce((s, a) => s + a.amount, 0)) }}</strong><small>Qoralamalar va moliyalashtirilganlar kiritilmagan</small></article><article><FileCheck2 /><span>Jamg‘armada</span><strong>{{ store.acts.filter(a => a.state === 'sent').length }}</strong><small>2 ish kunlik nazorat</small></article></section>
        <section class="gov-panel gov-table-wrap"><table><thead><tr><th>Dalolatnoma / loyiha</th><th>Oy</th><th>Summa</th><th>Kelishish</th><th>Holat</th><th>Nazorat sanasi</th><th></th></tr></thead><tbody><tr v-for="a in store.acts" :key="a.id"><td><b>{{ a.id }}</b><small>{{ store.project(a.projectId).title }}</small></td><td>{{ a.month }}</td><td class="gov-nowrap">{{ money(a.amount) }}</td><td>{{ Number(!!a.agreed.initiator) + Number(!!a.agreed.reviewer) }}/2 tomon</td><td><span class="gov-status" :data-state="a.state">{{ actLabels[a.state] }}</span></td><td :class="{ 'gov-late-text': actDue(a, store.holidays) && actDue(a, store.holidays) < today() }">{{ actDue(a, store.holidays) || '—' }}</td><td><RouterLink :to="`${base}/projects/${a.projectId}?tab=acts`">Jarayon <ArrowUpRight :size="14" /></RouterLink></td></tr></tbody></table></section>
      </template>

      <template v-else-if="pageKey === 'monitoring'">
        <div class="gov-toolbar"><b>{{ overdue.length }} ta muddat o‘tgan · bugun {{ today() }}</b><span>Javobsizlik statusni o‘zgartirmaydi.</span></div><section class="gov-panel gov-table-wrap"><table><thead><tr><th>Vazifa / loyiha</th><th>Bosqich</th><th>Mas’ul tomon</th><th>Nazorat sanasi</th><th>Natija</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td><RouterLink :to="`${base}/projects/${job.projectId}`"><b>{{ job.title }}</b></RouterLink><small>{{ job.id }}</small></td><td>{{ job.stage }}</td><td>{{ job.owner }}</td><td>{{ job.due }}</td><td><span :class="['gov-status', { overdue: job.due < today() }]">{{ job.due < today() ? 'Muddat o‘tgan' : 'Nazoratda' }}</span></td></tr></tbody></table></section><section class="gov-panel gov-pad"><h3>Ish kunlari kalendari · demo sozlama</h3><p class="gov-muted">Hisoblash boshlanish sanasidan keyingi kundan. Shanba/yakshanba chiqariladi. Rasmiy bayramlar avtomatik yuklanmaydi; quyida kiriting. Ish va dam olish kunlari ko‘chirilishi uchun ishlab chiqarish kalendari integratsiyasi zarur. Bu — buyruqda to‘liq bayon qilinmagan hisoblash sozlamasi.</p><div class="gov-toolbar"><input v-model="holidaysInput" placeholder="2026-10-15, 2026-10-16" aria-label="Dam olish sanalari"><button class="gov-primary" @click="saveHolidays">Kalendarga qo‘llash</button></div><small>Joriy sanalar: {{ store.holidays.join(', ') || 'Kiritilmagan' }}</small></section>
      </template>
      <template v-else-if="pageKey === 'rules'">
        <section class="gov-panel gov-pad"><h3>Ikki buyruq, yagona jarayon</h3><p>346-son buyruq — 17.12.2024. 79-son buyruq — 24.02.2026: Kengash ko‘rigi va BTRTR nomiga o‘zgarishlar.</p><div class="gov-rule-flow"><div v-for="(s, i) in pipeline" :key="s.id"><span>{{ i + 1 }}</span><b>{{ s.title }}</b><small>{{ s.rule }}</small></div></div></section><div class="gov-two"><section class="gov-panel gov-pad"><h3>Buyruqdan olingan majburiy qoidalar</h3><ul class="gov-rule-list"><li>Ijobiy xulosasiz TT tasdiqlash, shartnoma yoki xarid boshlash bloklanadi.</li><li>Kengash: kvorum kamida 2/3; qatnashganlarning oddiy ko‘pchilik ovozi.</li><li>Majlisni tashkil etish — 5 kun; nomuvofiq paketni qaytarish — 5 ish kuni.</li><li>Kengash qayta ishlashi — belgilangan muddat, ko‘pi bilan 30 ish kuni.</li><li>Texnik talab 5, texnik topshiriq 10, loyiha buyrug‘i 5 va shartnoma 2 ish kuni.</li><li>Hisobot keyingi oyning 5-sanasidan kechiktirmay; kelishish 3 ish kuni; Jamg‘armaga hujjatlar 10-sanasiga qadar; moliyalashtirish 2 ish kuni.</li><li>Loyiha qiymatida ish haqi jamg‘armasiga 5% ustama.</li></ul></section><section class="gov-panel gov-pad"><h3>Qo‘shimcha reglament va integratsiyalar</h3><ul class="gov-rule-list"><li>Dalolatnomaga e’tiroz shakli, tuzatish muddati va eskalatsiya tartibi.</li><li>Vaqtincha o‘rinbosarlik va serverda rol/ruxsat nazorati.</li><li>Elektron imzo, hujjat versiyasi, EDO va moliyaviy tizim APIlari.</li><li>Rasmiy tariflar jadvali: taqdim etilgan 346-son nusxada yo‘q.</li><li>Rasmiy ishlab chiqarish kalendari va muddatni hisoblash boshlanishi.</li><li>79-son buyruq ilova shakllaridagi eski bo‘lim nomini alohida o‘zgartirmagan.</li></ul><p class="gov-warning">Frontend demo ovozi elektron imzolangan bayonnoma emas. «Moliyalashtirilgan» — faqat demo qayd. Haqiqiy pul o‘tkazmasi bajarilmaydi.</p></section></div>
      </template>

      <dialog ref="createDialog" class="gov-dialog"><form @submit.prevent="createProject"><header><h2>Yangi loyiha tashabbusi</h2><button type="button" aria-label="Yopish" @click="createDialog?.close()"><X :size="20" /></button></header><p class="gov-muted">Avval loyiha kartasini yarating. To‘liq paket yuborishda tekshiriladi.</p><label class="gov-field">Loyiha nomi<input v-model="form.title" required placeholder="Loyiha nomini kiriting"></label><label class="gov-field">Tashabbuskor tashkilot<select v-model="form.organizationId" required @change="form.unitId = ''; form.ownerPositionId = ''"><option value="">Tanlang</option><option v-for="o in store.directory.organizations.filter(o => o.active)" :key="o.id" :value="o.id">{{ o.name }}</option></select></label><label class="gov-field">Tarkibiy bo‘linma<select v-model="form.unitId" required @change="form.ownerPositionId = ''"><option value="">Tanlang</option><option v-for="u in store.directory.units.filter(u => u.active && u.organizationId === form.organizationId)" :key="u.id" :value="u.id">{{ u.name }}</option></select></label><label class="gov-field">Mas’ul lavozim<select v-model="form.ownerPositionId" required><option value="">Tanlang</option><option v-for="p in store.directory.positions.filter(p => p.active && p.organizationId === form.organizationId && p.unitId === form.unitId && p.roles.includes('initiator'))" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label class="gov-field">Maqsad va vazifalar<textarea v-model="form.purpose" rows="3" /></label><p v-if="failure && feedback" class="gov-warning" role="alert">{{ feedback }}</p><footer><button type="button" @click="createDialog?.close()">Bekor qilish</button><button type="submit" class="gov-primary">Loyiha yaratish <ArrowRight :size="16" /></button></footer></form></dialog>
      <dialog ref="actDialog" class="gov-dialog"><form @submit.prevent="createAct"><header><h2>Yangi dalolatnoma</h2><button type="button" aria-label="Yopish" @click="actDialog?.close()"><X :size="20" /></button></header><label class="gov-field">Hisobot oyi<input v-model="actDraft.month" type="month" required :max="today().slice(0, 7)"></label><label class="gov-field">Hisobot oyi summasi, so‘m<input v-model.number="actDraft.amount" type="number" min="1" required></label><label class="gov-field">Loyiha bo‘yicha bajarilish, %<input v-model.number="actDraft.progress" type="number" min="0" max="100" required></label><label class="gov-field">Bajarilgan xizmatlar<textarea v-model="actDraft.services" required rows="3" /></label><label class="gov-field">Hisobot fayli<input type="file" required @change="chooseReport"></label><p v-if="failure && feedback" class="gov-warning" role="alert">{{ feedback }}</p><footer><button type="button" @click="actDialog?.close()">Bekor qilish</button><button type="submit" class="gov-primary">Qoralama yaratish</button></footer></form></dialog>
    </div>
  </PageContainer>
</template>
